{
  "name": "@ai-setting/opencode-cli",
  "version": "0.1.9",
  "description": "Minimal CLI to talk to an opencode server (HTTP + SSE)",
  "type": "module",
  "main": "./dist/cli.js",
  "module": "./dist/cli.js",
  "types": "./dist/cli.d.ts",
  "bin": {
    "opencode-cli": "./dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "dev": "tsc -p tsconfig.json --watch",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "bun test src/",
    "test:e2e": "OPENCODE_E2E=1 bun test src/e2e.test.ts",
    "test:all": "bun test src/ && OPENCODE_E2E=1 bun test src/e2e.test.ts",
    "prepublishOnly": "bun run typecheck && bun run build && bun run test",
    "publish:dry": "bun run scripts/publish.ts --dry-run --verify",
    "publish": "bun run scripts/publish.ts",
    "publish:latest": "bun run scripts/publish.ts --tag latest"
  },
  "keywords": [
    "opencode",
    "cli",
    "sse",
    "ai",
    "llm"
  ],
  "engines": {
    "bun": ">=1.0.0",
    "node": ">=18"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ai-setting/opencode-cli.git"
  },
  "homepage": "https://github.com/ai-setting/opencode-cli#readme",
  "bugs": {
    "url": "https://github.com/ai-setting/opencode-cli/issues"
  },
  "author": {
    "name": "ai-setting",
    "email": "ai-setting@users.noreply.github.com"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "bun-types": "latest",
    "typescript": "^5.4.0"
  }
}
